#[cfg(test)]
mod tests {
    use rigorix_engine::scored_evaluation::domain::backend::ScoringBackend;
    use rigorix_engine::scored_evaluation::infrastructure::backends::{
        HttpBackend, LocalBackend, McpBackend,
    };
    use std::collections::HashMap;

    #[test]
    fn test_infrastructure_layer_infrastructure_is_defined() {
        assert_eq!(LocalBackend::new("/tmp/s.sh", 1000).backend_name(), "local");
        assert_eq!(
            HttpBackend::new("http://x", HashMap::new(), 1000).backend_name(),
            "http"
        );
        assert_eq!(McpBackend::new("http://x", 1000).backend_name(), "mcp");
    }

    #[test]
    fn test_infrastructure_layer_infrastructure_interacts_with_none() {
        let backends: Vec<Box<dyn ScoringBackend>> = vec![
            Box::new(LocalBackend::new("/tmp/s.sh", 1000)),
            Box::new(HttpBackend::new("http://x", HashMap::new(), 1000)),
            Box::new(McpBackend::new("http://x", 1000)),
        ];
        assert_eq!(backends.len(), 3);
    }
}
